UPDATE pages SET body_html='<section id="core-team"><h2>Core Team</h2><p>For core people who support operations, systems and programme development. Recruitment only appears when officially open.</p></section><section id="volunteer"><h2>Volunteer</h2><p>Each programme has its own requirements and form; there is no one oversized form for every volunteer role.</p></section><section id="learner"><h2>Learner</h2><p>Learners register through the relevant programme when registration is open.</p></section><section><h2>Send an expression of interest</h2><form class="public-form" data-form-type="participation"><label>Full name<input name="name" required maxlength="120"></label><label>Email<input name="email" type="email" required maxlength="160"></label><label>Phone number<input name="phone" maxlength="40"></label><label>Interest / message<textarea name="message" required maxlength="3000"></textarea></label><label class="check"><input name="consent" type="checkbox" required> I consent to Sky First using this information to receive and respond to my request.</label><button class="button primary">Send information</button><p class="form-status" aria-live="polite"></p></form></section>',updated_at=CURRENT_TIMESTAMP WHERE lang='en' AND slug='tham-gia';

UPDATE pages SET body_html='<p>Sky First receives collaboration proposals for co-organised programmes, professional support, communication/community connection and suitable resource support. Each proposal is considered according to direction, resources and practical scope.</p><form class="public-form" data-form-type="collaboration"><label>Full name<input name="name" required maxlength="120"></label><label>Email<input name="email" type="email" required maxlength="160"></label><label>Organisation<input name="organisation" maxlength="180"></label><label>Proposal title<input name="subject" maxlength="180"></label><label>Proposal details<textarea name="message" required maxlength="3000"></textarea></label><label class="check"><input name="consent" type="checkbox" required> I consent to Sky First using this information to process the proposal.</label><button class="button primary">Send proposal</button><p class="form-status" aria-live="polite"></p></form>',updated_at=CURRENT_TIMESTAMP WHERE lang='en' AND slug='hop-tac';

UPDATE pages SET body_html='<div class="contact-cards"><article><h2>Official contact channels</h2><p><a href="mailto:skyfirst.ec@gmail.com">skyfirst.ec@gmail.com</a><br><a href="mailto:hotro.sfn@gmail.com">hotro.sfn@gmail.com</a><br>Hotline/Zalo: 0924 910 210</p></article><article><h2>Safety notice</h2><p>Sky First never asks for passwords, OTP codes or sign-in details by email, public form or message.</p></article></div><form class="public-form" data-form-type="contact"><label>Full name<input name="name" required maxlength="120"></label><label>Contact email<input name="email" type="email" required maxlength="160"></label><label>Phone number<input name="phone" maxlength="40"></label><label>Organisation<input name="organisation" maxlength="180"></label><label>Subject<input name="subject" maxlength="180"></label><label>Message<textarea name="message" required maxlength="3000"></textarea></label><label class="check"><input name="consent" type="checkbox" required> I consent to Sky First using this information to contact me and process this request.</label><button class="button primary">Send enquiry</button><p class="form-status" aria-live="polite"></p></form>',updated_at=CURRENT_TIMESTAMP WHERE lang='en' AND slug='lien-he';
